/**
 * returns 0 on success and -1, -2 or -3 on failure.
 * -1 when the variable does not exist and -2 if the value is not defined in the enum and -3 if the operation or server index is not found
 */
int OAIConfigmgrApi::setDefaultServerValue(int serverIndex, const QString &operation, const QString &variable, const QString &value) {
    auto it = _serverConfigs.find(operation);
    if (it != _serverConfigs.end() && serverIndex < it.value().size()) {
      return _serverConfigs[operation][serverIndex].setDefaultValue(variable,value);
    }
    return -3;
}

/**
 * Sets the server index.
 * @param operation The id to the target operation.
 * @param serverIndex The server index.
 */
void OAIConfigmgrApi::setServerIndex(const QString &operation, int serverIndex) {
    if (_serverIndices.contains(operation) && serverIndex < _serverConfigs.find(operation).value().size()) {
        _serverIndices[operation] = serverIndex;
    }
}

void OAIConfigmgrApi::setServerIndex(int serverIndex) {
    for (auto keyIt = _serverIndices.keyBegin(); keyIt != _serverIndices.keyEnd(); keyIt++) {
        setServerIndex(*keyIt, serverIndex);
    }
}

void OAIConfigmgrApi::setApiKey(const QString &apiKeyName, const QString &apiKey) {
    _apiKeys.insert(apiKeyName, apiKey);
}

void OAIConfigmgrApi::setBearerToken(const QString &token) {
    _bearerToken = token;
}

void OAIConfigmgrApi::setUsername(const QString &username) {
    _username = username;
}

void OAIConfigmgrApi::setPassword(const QString &password) {
    _password = password;
}


void OAIConfigmgrApi::setTimeOut(const int timeOut) {
    _timeOut = timeOut;
}

void OAIConfigmgrApi::setWorkingDirectory(const QString &path) {
    _workingDirectory = path;
}

void OAIConfigmgrApi::setNetworkAccessManager(QNetworkAccessManager* manager) {
    _manager = manager;
}

/**
 * Appends a new ServerConfiguration to the config map for a specific operation.
 * @param operation The id to the target operation.
 * @param url A string that contains the URL of the server
 * @param description A String that describes the server
 * @param variables A map between a variable name and its value. The value is used for substitution in the server's URL template.
 * returns the index of the new server config on success and -1 if the operation is not found
 */
int OAIConfigmgrApi::addServerConfiguration(const QString &operation, const QUrl &url, const QString &description, const QMap<QString, OAIServerVariable> &variables) {
    if (_serverConfigs.contains(operation)) {
        _serverConfigs[operation].append(OAIServerConfiguration(
                    url,
                    description,
                    variables));
        return _serverConfigs[operation].size()-1;
    } else {
        return -1;
    }
}

/**
 * Appends a new ServerConfiguration to the config map for a all operations and sets the index to that server.
 * @param url A string that contains the URL of the server
 * @param description A String that describes the server
 * @param variables A map between a variable name and its value. The value is used for substitution in the server's URL template.
 */
void OAIConfigmgrApi::setNewServerForAllOperations(const QUrl &url, const QString &description, const QMap<QString, OAIServerVariable> &variables) {
    for (auto keyIt = _serverIndices.keyBegin(); keyIt != _serverIndices.keyEnd(); keyIt++) {
        setServerIndex(*keyIt, addServerConfiguration(*keyIt, url, description, variables));
    }
}

/**
 * Appends a new ServerConfiguration to the config map for an operations and sets the index to that server.
 * @param URL A string that contains the URL of the server
 * @param description A String that describes the server
 * @param variables A map between a variable name and its value. The value is used for substitution in the server's URL template.
 */
void OAIConfigmgrApi::setNewServer(const QString &operation, const QUrl &url, const QString &description, const QMap<QString, OAIServerVariable> &variables) {
    setServerIndex(operation, addServerConfiguration(operation, url, description, variables));
}

void OAIConfigmgrApi::addHeaders(const QString &key, const QString &value) {
    _defaultHeaders.insert(key, value);
}

