void OAIConfigmgrApi::comAdobeCqSecurityHcDispatcherImplDispatcherAccessHealthCheckCallback(OAIHttpRequestWorker *worker) {
    QString error_str = worker->error_str;
    QNetworkReply::NetworkError error_type = worker->error_type;

    if (worker->error_type != QNetworkReply::NoError) {
        error_str = QString("%1, %2").arg(worker->error_str, QString(worker->response));
    }
    OAIComAdobeCqSecurityHcDispatcherImplDispatcherAccessHealthCheckInfo output(QString(worker->response));
    worker->deleteLater();

    if (worker->error_type == QNetworkReply::NoError) {
        Q_EMIT comAdobeCqSecurityHcDispatcherImplDispatcherAccessHealthCheckSignal(output);
        Q_EMIT comAdobeCqSecurityHcDispatcherImplDispatcherAccessHealthCheckSignalFull(worker, output);
    } else {
        Q_EMIT comAdobeCqSecurityHcDispatcherImplDispatcherAccessHealthCheckSignalError(output, error_type, error_str);
        Q_EMIT comAdobeCqSecurityHcDispatcherImplDispatcherAccessHealthCheckSignalErrorFull(worker, error_type, error_str);
    }
}

