void OAIConfigmgrApi::comAdobeCqSocialSyncImplUserSyncListenerImplCallback(OAIHttpRequestWorker *worker) {
    QString error_str = worker->error_str;
    QNetworkReply::NetworkError error_type = worker->error_type;

    if (worker->error_type != QNetworkReply::NoError) {
        error_str = QString("%1, %2").arg(worker->error_str, QString(worker->response));
    }
    OAIComAdobeCqSocialSyncImplUserSyncListenerImplInfo output(QString(worker->response));
    worker->deleteLater();

    if (worker->error_type == QNetworkReply::NoError) {
        Q_EMIT comAdobeCqSocialSyncImplUserSyncListenerImplSignal(output);
        Q_EMIT comAdobeCqSocialSyncImplUserSyncListenerImplSignalFull(worker, output);
    } else {
        Q_EMIT comAdobeCqSocialSyncImplUserSyncListenerImplSignalError(output, error_type, error_str);
        Q_EMIT comAdobeCqSocialSyncImplUserSyncListenerImplSignalErrorFull(worker, error_type, error_str);
    }
}

