void OAIConfigmgrApi::comAdobeGraniteAuthOauthProviderCallback(OAIHttpRequestWorker *worker) {
    QString error_str = worker->error_str;
    QNetworkReply::NetworkError error_type = worker->error_type;

    if (worker->error_type != QNetworkReply::NoError) {
        error_str = QString("%1, %2").arg(worker->error_str, QString(worker->response));
    }
    OAIComAdobeGraniteAuthOauthProviderInfo output(QString(worker->response));
    worker->deleteLater();

    if (worker->error_type == QNetworkReply::NoError) {
        Q_EMIT comAdobeGraniteAuthOauthProviderSignal(output);
        Q_EMIT comAdobeGraniteAuthOauthProviderSignalFull(worker, output);
    } else {
        Q_EMIT comAdobeGraniteAuthOauthProviderSignalError(output, error_type, error_str);
        Q_EMIT comAdobeGraniteAuthOauthProviderSignalErrorFull(worker, error_type, error_str);
    }
}

