void OAIConfigmgrApi::comDayCqWcmMsmImplLiveRelationshipManagerImplCallback(OAIHttpRequestWorker *worker) {
    QString error_str = worker->error_str;
    QNetworkReply::NetworkError error_type = worker->error_type;

    if (worker->error_type != QNetworkReply::NoError) {
        error_str = QString("%1, %2").arg(worker->error_str, QString(worker->response));
    }
    OAIComDayCqWcmMsmImplLiveRelationshipManagerImplInfo output(QString(worker->response));
    worker->deleteLater();

    if (worker->error_type == QNetworkReply::NoError) {
        Q_EMIT comDayCqWcmMsmImplLiveRelationshipManagerImplSignal(output);
        Q_EMIT comDayCqWcmMsmImplLiveRelationshipManagerImplSignalFull(worker, output);
    } else {
        Q_EMIT comDayCqWcmMsmImplLiveRelationshipManagerImplSignalError(output, error_type, error_str);
        Q_EMIT comDayCqWcmMsmImplLiveRelationshipManagerImplSignalErrorFull(worker, error_type, error_str);
    }
}

