void OAIConfigmgrApi::orgApacheJackrabbitOakSegmentSegmentNodeStoreFactoryCallback(OAIHttpRequestWorker *worker) {
    QString error_str = worker->error_str;
    QNetworkReply::NetworkError error_type = worker->error_type;

    if (worker->error_type != QNetworkReply::NoError) {
        error_str = QString("%1, %2").arg(worker->error_str, QString(worker->response));
    }
    OAIOrgApacheJackrabbitOakSegmentSegmentNodeStoreFactoryInfo output(QString(worker->response));
    worker->deleteLater();

    if (worker->error_type == QNetworkReply::NoError) {
        Q_EMIT orgApacheJackrabbitOakSegmentSegmentNodeStoreFactorySignal(output);
        Q_EMIT orgApacheJackrabbitOakSegmentSegmentNodeStoreFactorySignalFull(worker, output);
    } else {
        Q_EMIT orgApacheJackrabbitOakSegmentSegmentNodeStoreFactorySignalError(output, error_type, error_str);
        Q_EMIT orgApacheJackrabbitOakSegmentSegmentNodeStoreFactorySignalErrorFull(worker, error_type, error_str);
    }
}

