void OAIConfigmgrApi::orgApacheSlingDistributionAgentImplSyncDistributionAgentFactoryCallback(OAIHttpRequestWorker *worker) {
    QString error_str = worker->error_str;
    QNetworkReply::NetworkError error_type = worker->error_type;

    if (worker->error_type != QNetworkReply::NoError) {
        error_str = QString("%1, %2").arg(worker->error_str, QString(worker->response));
    }
    OAIOrgApacheSlingDistributionAgentImplSyncDistributionAgentFactoryInfo output(QString(worker->response));
    worker->deleteLater();

    if (worker->error_type == QNetworkReply::NoError) {
        Q_EMIT orgApacheSlingDistributionAgentImplSyncDistributionAgentFactorySignal(output);
        Q_EMIT orgApacheSlingDistributionAgentImplSyncDistributionAgentFactorySignalFull(worker, output);
    } else {
        Q_EMIT orgApacheSlingDistributionAgentImplSyncDistributionAgentFactorySignalError(output, error_type, error_str);
        Q_EMIT orgApacheSlingDistributionAgentImplSyncDistributionAgentFactorySignalErrorFull(worker, error_type, error_str);
    }
}

